        negative = True
        s = s[1:-1].strip()
        if not s:
            return None
    cleaned = s.replace("$", "").replace(",", "").strip()
    if not cleaned:
        return None
    try:
        value = float(cleaned)
    except ValueError:
        return None
    return -value if negative else value


def summarize_expenses(csv_text):
